args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?olderFilm ?olderFilmLabel ?olderDirector ?olderDirectorLabel ?olderBirth ?youngerFilm ?youngerDirector ?youngerBirth WHERE {
  VALUES (?filmA ?filmB) {(dbr:A_Wrong_Way_to_Love dbr:Ever_Since_We_Love)}
  ?filmA dbo:director ?dirA .
  ?filmB dbo:director ?dirB .

  OPTIONAL { ?dirA dbo:birthDate ?bdA . }
  OPTIONAL { ?dirA dbp:birthDate ?bdA_2 . }
  OPTIONAL { ?dirB dbo:birthDate ?bdB . }
  OPTIONAL { ?dirB dbp:birthDate ?bdB_2 . }

  BIND(COALESCE(?bdA, ?bdA_2) AS ?bdA_final)
  BIND(COALESCE(?bdB, ?bdB_2) AS ?bdB_final)

  FILTER(bound(?bdA_final) && bound(?bdB_final))

  BIND(IF(str(?bdA_final) < str(?bdB_final), ?filmA, ?filmB) AS ?olderFilm)
  BIND(IF(str(?bdA_final) < str(?bdB_final), ?dirA, ?dirB) AS ?olderDirector)
  BIND(IF(str(?bdA_final) < str(?bdB_final), ?bdA_final, ?bdB_final) AS ?olderBirth)
  BIND(IF(str(?bdA_final) < str(?bdB_final), ?filmB, ?filmA) AS ?youngerFilm)
  BIND(IF(str(?bdA_final) < str(?bdB_final), ?dirB, ?dirA) AS ?youngerDirector)
  BIND(IF(str(?bdA_final) < str(?bdB_final), ?bdB_final, ?bdA_final) AS ?youngerBirth)

  OPTIONAL { ?olderFilm rdfs:label ?olderFilmLabel . FILTER (lang(?olderFilmLabel) = "en") }
  OPTIONAL { ?olderDirector rdfs:label ?olderDirectorLabel . FILTER (lang(?olderDirectorLabel) = "en") }
}
LIMIT 1

